style.css:
@-moz-document domain("character.ai") {
body {
    background: url("https://files.catbox.moe/wgb5n9.gif") no-repeat center center fixed !important;
    background-size: contain !important; /* Show the whole GIF */
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    color: black !important;
    font-weight: bold !important;
  }

  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    backdrop-filter: blur(2px); /* Reduce blur so GIF shows better */
    background: rgba(255, 255, 255, 0.2); /* Light overlay for contrast */
    z-index: -1;
  }

  .chat, .message, .input-box, 
  .chat *, .message *, .input-box * {
    background: rgba(255, 255, 255, 0.3) !important;
    color: black !important;
    font-weight: bold !important;
  }
}
